create type public.app_role as enum ('learner','parent','teacher','admin');
create table public.profiles (id uuid primary key references auth.users on delete cascade, display_name text not null default 'Learner', role public.app_role not null default 'learner', locale text not null default 'en', created_at timestamptz not null default now());
create table public.lessons (id uuid primary key default gen_random_uuid(), owner_id uuid not null references public.profiles(id) on delete cascade, topic text not null, content jsonb not null, source_type text not null default 'ai', created_at timestamptz not null default now());
create table public.mastery (id uuid primary key default gen_random_uuid(), learner_id uuid not null references public.profiles(id) on delete cascade, subject text not null, skill text not null, score numeric not null check(score between 0 and 100), updated_at timestamptz not null default now(), unique(learner_id,skill));
create table public.quiz_attempts (id uuid primary key default gen_random_uuid(), learner_id uuid not null references public.profiles(id) on delete cascade, lesson_id uuid references public.lessons(id) on delete set null, score numeric not null check(score between 0 and 100), answers jsonb not null default '[]', created_at timestamptz not null default now());
create table public.documents (id uuid primary key default gen_random_uuid(), owner_id uuid not null references public.profiles(id) on delete cascade, name text not null, storage_path text not null, extracted_text text, created_at timestamptz not null default now());
create table public.document_chunks (id uuid primary key default gen_random_uuid(), document_id uuid not null references public.documents(id) on delete cascade, body text not null, embedding extensions.vector(1536), ordinal int not null);
create table public.entitlements (id uuid primary key default gen_random_uuid(), owner_id uuid not null references public.profiles(id) on delete cascade, provider text not null, provider_customer_id text, plan text not null default 'free', status text not null default 'active', unique(provider,provider_customer_id));
alter table public.profiles enable row level security; alter table public.lessons enable row level security; alter table public.mastery enable row level security; alter table public.quiz_attempts enable row level security; alter table public.documents enable row level security; alter table public.document_chunks enable row level security; alter table public.entitlements enable row level security;
create policy "profiles own" on public.profiles for all using (id=auth.uid()) with check (id=auth.uid());
create policy "lessons own" on public.lessons for all using (owner_id=auth.uid()) with check (owner_id=auth.uid());
create policy "mastery own" on public.mastery for all using (learner_id=auth.uid()) with check (learner_id=auth.uid());
create policy "attempts own" on public.quiz_attempts for all using (learner_id=auth.uid()) with check (learner_id=auth.uid());
create policy "documents own" on public.documents for all using (owner_id=auth.uid()) with check (owner_id=auth.uid());
create policy "chunks via document" on public.document_chunks for all using (exists(select 1 from public.documents d where d.id=document_id and d.owner_id=auth.uid()));
create policy "entitlements own" on public.entitlements for select using (owner_id=auth.uid());
